pub fn crossings(previous: Option<f32>, current: f32, thresholds: &[u8]) -> Vec<u8> { let Some(previous)=previous else{return vec![]}; if !current.is_finite()||!previous.is_finite(){return vec![]}; thresholds.iter().copied().filter(|t|previous<*t as f32&&current>=*t as f32).collect() }
#[cfg(test)] mod tests { use super::*; #[test]fn emits_each_crossed_threshold_in_order(){assert_eq!(crossings(Some(74.0),96.0,&[75,90,95]),vec![75,90,95]);} #[test]fn first_observation_does_not_backfill_alerts(){assert!(crossings(None,96.0,&[75,90,95]).is_empty());} #[test]fn falling_usage_does_not_alert(){assert!(crossings(Some(96.0),20.0,&[75,90,95]).is_empty());}}
